// Same signature gate as the owner write path, same secret, SEPARATE verb space.
// It is deliberately NOT an entry in OWNER_ACTIONS: the write path's whole auditability rests on that
// list holding exactly one verb, and widening it to let a test read would trade the security model for
// convenience. A different workflow with its own allow-list costs nothing and keeps that claim true.
const crypto = require('crypto');
const item = $input.first();
let raw = '', src = 'none';
if (item.binary && item.binary.data && item.binary.data.data) {
  raw = Buffer.from(item.binary.data.data, 'base64').toString('utf8'); src = 'binary';
} else if (typeof item.json.body === 'string') { raw = item.json.body; src = 'json.body:string'; }
else if (item.json.body && typeof item.json.body === 'object') { raw = JSON.stringify(item.json.body); src = 'json.body:reserialised'; }

const given = (item.json.headers || {})['x-owner-signature'];
const secret = $env.OWNER_HMAC_SECRET;
let sig_valid = false;
if (typeof secret === 'string' && secret && typeof given === 'string' && raw) {
  const mine = crypto.createHmac('sha256', secret).update(raw, 'utf8').digest('hex');
  if (given.length === mine.length) sig_valid = crypto.timingSafeEqual(Buffer.from(mine,'utf8'), Buffer.from(given,'utf8'));
}
let p = {}; try { p = JSON.parse(raw); } catch (e) { p = {}; }

// Injection boundary, not a trust boundary — both values are interpolated into Airtable formulas.
const RECORD_ID = /^rec[A-Za-z0-9]{14}$/;
const MESSAGE_ID = /^[A-Za-z0-9._-]{1,64}$/;
const record_id = typeof p.record_id === 'string' ? p.record_id : '';
const messageId = typeof p.messageId === 'string' ? p.messageId : '';
return [{ json: { sig_valid, _raw_source: src,
  action_ok: p.action === 'read_drill_state' && RECORD_ID.test(record_id) && MESSAGE_ID.test(messageId),
  record_id, messageId } }];

// "stage|last_intent|markerCount" — the three facts run-d11 needs and nothing else.
// markerCount is the MUTATION COUNTER: state equality cannot tell "no second write" from "a second
// IDENTICAL write", because setting stage='new' twice leaves the row looking the same. One full pass
// writes exactly one dedupe marker, so the count is what actually discriminates.
const ctx = $('Verify Drill Signature').first().json;
const conv = $('Read Conversation').all().filter(i => i.json && i.json.id);
const marks = $input.all().filter(i => i.json && i.json.id);
const f = conv[0] ? (conv[0].json.fields || conv[0].json) : null;
const state = f ? ((f.stage || '') + '|' + (f.last_intent || '')) : 'NOT-FOUND';
return [{ json: { line: state + '|' + marks.length } }];
